// AATPE - Logging system (async buffered log with rotation)
// Auto-generated by phase-2 split - pure mechanical move, no logic changes.
#include "aatped.h"
#include <cstdarg>
#include <cstdio>
#include <cstring>
#include <cerrno>
#include <ctime>
#include <mutex>
#include <thread>
#include <chrono>
#include <fcntl.h>     // open/O_* flags (issue 3)
#include <sys/stat.h>   // chmod/fchmod (#73 log-rotation perms)
#include <unistd.h>     // fileno

using namespace aatpe;

// aatpeStrError / aatpeErrStr are now defined inline in aatped_logging.h so any
// production TU can call them without linking this .o (unit-test recipes do not).

std::atomic<int> g_logLevel{2};  // non-static so LOG_FORCE macro in other TUs can access
static FILE* g_logFp = nullptr;
static std::mutex g_logMutex;
std::atomic<unsigned int> g_debugSampleCounter{0};

// Async buffered logging
static std::string g_logBuffer;
static int g_logBufferCount = 0;
static std::atomic<bool> g_logFlushThreadRunning{false};
static std::thread g_logFlushThread;
static constexpr size_t kLogBufferMaxBytes = 4096;
static constexpr int kLogBufferMaxCount = 100;
static constexpr int kLogFlushIntervalMs = 100;
// A8 (fuzz hang root-cause): the null-fp orphan branch (log rotation window, or a
// fuzz process that never called logInit()) buffers lines with no drain. In normal
// production the rotation window is brief, but if the log sink is persistently
// unavailable the buffer must not grow without bound. Hard-cap the orphan buffer at
// 1MiB; once full, further orphan lines are dropped (counted) until the fp returns.
static constexpr size_t kLogBufferOrphanCapBytes = 1u << 20;  // 1 MiB
static std::atomic<unsigned long> g_logDroppedOrphan{0};
// #75: log file permissions — must be 0600 (root-only). The log contains
// package names, thread names, TIDs and scheduling decisions.
static const mode_t kLogFileMode = 0600;

// Must hold g_logMutex before calling
static void flushLogBufferLocked() {
    if (g_logBuffer.empty() || !g_logFp) return;
    // P3-26: check fwrite return value (short write / disk full).
    size_t nw = fwrite(g_logBuffer.data(), 1, g_logBuffer.size(), g_logFp);
    if (nw != g_logBuffer.size()) {
        // best-effort: log to stderr, but don't crash.
        fprintf(stderr, "AATPE: log short write %zu/%zu\n", nw, g_logBuffer.size());
    }
    g_logBuffer.clear();
    g_logBufferCount = 0;
    fflush(g_logFp);
}

void logFlush() {
    std::lock_guard<std::mutex> lock(g_logMutex);
    flushLogBufferLocked();
}

static void logFlushThreadFunc() {
    while (g_logFlushThreadRunning.load(std::memory_order_acquire)) {
        std::this_thread::sleep_for(std::chrono::milliseconds(kLogFlushIntervalMs));
        std::lock_guard<std::mutex> lock(g_logMutex);
        if (!g_logBuffer.empty()) {
            flushLogBufferLocked();
        }
    }
}

static void startLogFlushThread() {
    if (g_logFlushThreadRunning.load()) return;
    g_logFlushThreadRunning.store(true, std::memory_order_release);
    try {
        g_logFlushThread = std::thread(logFlushThreadFunc);
    } catch (const std::exception& e) {
        g_logFlushThreadRunning.store(false);
        fprintf(stderr, "AATPE: logFlushThread start failed: %s\n", e.what());
    }
}

void logShutdown() {
    g_logFlushThreadRunning.store(false, std::memory_order_release);
    if (g_logFlushThread.joinable()) {
        g_logFlushThread.join();
    }
    std::lock_guard<std::mutex> lock(g_logMutex);
    flushLogBufferLocked();
}

void logInit() {
    // P2-5: set umask(0077) so fopen("a") creates the file 0600 from the start,
    // closing the race window between fopen and fchmod.
    mode_t oldMask = umask(0077);
    g_logFp = fopen(LOG_FILE, "a");
    umask(oldMask);
    if (g_logFp) {
        // #75: ensure log file is 0600 root-only from creation (umask may be 022).
        // C-013: check fileno() return value before fchmod.
        // P3-25: check fchmod return value.
        int fd = fileno(g_logFp);
        if (fd >= 0 && fchmod(fd, kLogFileMode) != 0) {
            char ebuf[128];
            LOG_WARN("logInit fchmod failed: %s", aatpeStrError(errno, ebuf, sizeof(ebuf)));
        }
    } else {
        char ebuf[128];
        fprintf(stderr, "AATPE: Cannot open log file %s: %s\n", LOG_FILE,
                aatpeStrError(errno, ebuf, sizeof(ebuf)));
    }
}

// Re-open log file after daemon(). On Android/Bionic, daemon()
// closes all file descriptors > 2 (including g_logFp's fd), causing all
// subsequent LOG_* calls to silently fail. This must be called after daemon().
// Also ensure RUN_DIR exists BEFORE fopen — previously mkdir()
// was called AFTER logReinit() in main(), so on a fresh boot where /dev/aatpe
// doesn't exist yet, fopen() failed with ENOENT and the error went to stderr
// (which daemon() redirected to /dev/null). Result: total log blackout.
void logReinit() {
    std::lock_guard<std::mutex> lock(g_logMutex);
    // flush any buffered entries before closing
    flushLogBufferLocked();
    if (g_logFp) {
        // P3-27: check fclose return value.
        if (fclose(g_logFp) != 0) {
            char ebuf[128];
            fprintf(stderr, "AATPE: logReinit fclose failed: %s\n",
                    aatpeStrError(errno, ebuf, sizeof(ebuf)));
        }
        g_logFp = nullptr;
    }
    // Ensure the log directory exists (idempotent — safe to call repeatedly)
    // RUN_DIR holds the token/control, keep it root-only (0700).
    mkdirIfNotExist(RUN_DIR, 0700);
    // P2-5: umask(0077) closes the fopen→fchmod race window.
    mode_t oldMask = umask(0077);
    g_logFp = fopen(LOG_FILE, "a");
    if (!g_logFp) {
        // F-A6-04[P3]: last-resort fallback in the world-writable /data/local/tmp.
        // Open with O_NOFOLLOW so a locally-planted symlink cannot redirect root
        // log writes through an attacker-chosen target; if the path is (or becomes)
        // a symlink, open() fails ELOOP and we fall through to stderr instead of
        // writing through it. Born 0600 via the open() mode.
        int fbFd = ::open("/data/local/tmp/aatpe_daemon.log",
                          O_WRONLY | O_CREAT | O_APPEND | O_NOFOLLOW | O_CLOEXEC, 0600);
        if (fbFd >= 0) {
            g_logFp = ::fdopen(fbFd, "a");
            if (!g_logFp) ::close(fbFd);
        }
        if (!g_logFp) {
            umask(oldMask);
            // Cannot log anywhere — write to stderr (likely /dev/null after daemon)
            char ebuf[128];
            fprintf(stderr, "AATPE: logReinit: FATAL Cannot open log file %s: %s\n",
                    LOG_FILE, aatpeStrError(errno, ebuf, sizeof(ebuf)));
            return;
        }
        // C-013: check fileno() before fchmod. P3-25: check return.
        { int fd = fileno(g_logFp); if (fd >= 0 && fchmod(fd, kLogFileMode) != 0) {
            char ebufF[128];
            fprintf(g_logFp, "[LOG] WARNING: logReinit fallback fchmod failed: %s\n",
                    aatpeStrError(errno, ebufF, sizeof(ebufF))); } }
        char ebuf[128];
        fprintf(g_logFp, "[LOG] WARNING: primary log %s unavailable (%s), using fallback\n",
                LOG_FILE, aatpeStrError(errno, ebuf, sizeof(ebuf)));
    }
    umask(oldMask);
    // #75: enforce 0600 root-only on every (re)open. The log contains package
    // names, thread names, TIDs and scheduling decisions — must not be readable
    // by other apps on a production device.
    // C-013: check fileno() before fchmod. P3-25: check return.
    { int fd = fileno(g_logFp); if (fd >= 0 && fchmod(fd, kLogFileMode) != 0) {
        // P1 round7: g_logMutex held; LOG_WARN->logMsg would self-deadlock on the mutex.
        char ebufL[128];
        fprintf(g_logFp, "[LOG] WARNING: logReinit fchmod failed: %s\n",
                aatpeStrError(errno, ebufL, sizeof(ebufL))); } }
    // Verification log — MUST appear in daemon log to prove fd was restored
    fprintf(g_logFp, "[LOG] reinitialized after daemonize, fd restored\n");
    fflush(g_logFp);
    // start async flush thread after log file is ready
    startLogFlushThread();
}

// D-09: Log rotation - rotate when file exceeds 8MB.
// #73: after rotation the new log file and the rotated .1 MUST keep the same
// restrictive permissions (0600 root-only). fopen("a") otherwise inherits the
// process umask, which on some devices leaves the log world-readable.
// P2-12: use the single canonical constant from aatpe-constants.h.
static const long long kMaxLogSize = aatpe::logging::kMaxLogSizeBytes;

// P1-fix (issue 4): split rotation into a cheap check (ftell) and the heavy
// I/O (fclose/rename/fopen). The cheap check runs under g_logMutex on every
// logMsg; the heavy I/O is performed AFTER releasing g_logMutex so that other
// log writers are not blocked for the duration of disk I/O. A separate
// g_logRotationMutex serializes concurrent rotation triggers.
static std::mutex g_logRotationMutex;

// Must hold g_logMutex. Cheap: just ftell.
static bool logRotationNeededLocked() {
    if (!g_logFp) return false;
    long long pos = ftell(g_logFp);
    return pos > kMaxLogSize;
}

// Must hold g_logRotationMutex. Acquires/releases g_logMutex internally.
static void performLogRotation() {
    // We don't hold g_logMutex here; take it briefly to snapshot the fp,
    // then release for the heavy I/O.
    FILE* fpToClose = nullptr;
    {
        std::lock_guard<std::mutex> lock(g_logMutex);
        if (!g_logFp) return;
        double pos = ftell(g_logFp);
        if (pos <= kMaxLogSize) return;  // another thread already rotated
        fpToClose = g_logFp;
        g_logFp = nullptr;
    }
    // Heavy I/O outside g_logMutex.
    fclose(fpToClose);
    std::string oldPath = std::string(LOG_FILE) + ".1";
    char ebuf[128];
    if (rename(LOG_FILE, oldPath.c_str()) != 0) {
        // LOG_WARN is not safe here (would recurse into logMsg); use stderr.
        int e = errno;
        fprintf(stderr, "AATPE: log rotation rename failed: %s\n",
                aatpeStrError(e, ebuf, sizeof(ebuf)));
    }
    if (chmod(oldPath.c_str(), kLogFileMode) != 0 && errno != ENOENT) {
        int e = errno;
        fprintf(stderr, "AATPE: log rotation chmod old failed: %s\n",
                aatpeStrError(e, ebuf, sizeof(ebuf)));
    }
    // Open new log directly with 0600 (no umask window).
    mode_t oldMask = umask(0077);
    FILE* newFp = fopen(LOG_FILE, "a");
    umask(oldMask);
    if (newFp) {
        int fd = fileno(newFp);
        if (fd >= 0 && fchmod(fd, kLogFileMode) != 0) {
            int e = errno;
            fprintf(stderr, "AATPE: log rotation fchmod failed: %s\n",
                    aatpeStrError(e, ebuf, sizeof(ebuf)));
        }
    } else {
        int e = errno;
        fprintf(stderr, "AATPE: log rotation failed: %s\n",
                aatpeStrError(e, ebuf, sizeof(ebuf)));
    }
    // Publish new fp under lock.
    std::lock_guard<std::mutex> lock(g_logMutex);
    if (g_logFp) fclose(g_logFp);  // shouldn't happen, but be safe
    g_logFp = newFp;
}

void logMsg(int level, const char* fmt, ...) {
    if (level > g_logLevel.load()) return;
    const char* tags[] = {"ERROR", "WARN ", "INFO ", "DEBUG", "TRACE"};
    const char* tag = (level >= 0 && level <= 4) ? tags[level] : "INFO ";
    time_t now = time(nullptr);
    struct tm tm_buf;
    localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_buf);

    // Format message body first (no lock needed)
    char msgBuf[4096];
    va_list args;
    va_start(args, fmt);
    int msgLen = vsnprintf(msgBuf, sizeof(msgBuf), fmt, args);
    va_end(args);
    if (msgLen < 0) msgLen = 0;
    if (msgLen >= (int)sizeof(msgBuf)) msgLen = (int)sizeof(msgBuf) - 1;

    // P2 log-injection hardening: the message args can carry kernel-controlled
    // strings (thread comm, package name, cpuset path). A '\n' inside the body
    // would forge a second, attacker-shaped log line on the next byte. Replace
    // CR/LF/TAB with a space so every LOG_* call produces exactly one physical line.
    // F-A6-09[P3]: ALSO strip every other C0 control byte (<0x20) and DEL (0x7f)
    // — notably ESC (0x1b), which an attacker-influenced comm/package name could
    // embed to drive terminal escape sequences (color/clearing/cursor move) when an
    // operator cats the log. Replace with '?' (visible, terminal-neutral).
    for (int i = 0; i < msgLen; i++) {
        unsigned char c = (unsigned char)msgBuf[i];
        if (c == '\n' || c == '\r' || c == '\t') msgBuf[i] = ' ';
        else if (c < 0x20 || c == 0x7f) msgBuf[i] = '?';
    }

    // Build complete line
    char lineBuf[4200];
    int lineLen = snprintf(lineBuf, sizeof(lineBuf), "[%s] [%s] %.*s\n", ts, tag, msgLen, msgBuf);
    if (lineLen < 0) lineLen = 0;
    if (lineLen >= (int)sizeof(lineBuf)) lineLen = (int)sizeof(lineBuf) - 1;

    std::unique_lock<std::mutex> lock(g_logMutex);
    // P1-fix (issue 4): cheap ftell check under lock; if rotation needed,
    // release g_logMutex for the heavy I/O and re-acquire for the write.
    if (logRotationNeededLocked()) {
        lock.unlock();
        {
            std::lock_guard<std::mutex> rlock(g_logRotationMutex);
            performLogRotation();
        }
        lock.lock();
    }
    if (!g_logFp) {
        // G1-002: rotation window (fpToClose snapshotted, g_logFp=nullptr until
        // the new fp is published). Buffer the line; the flush thread (or the next
        // direct write) drains g_logBuffer once the new fp lands.
        // A8: hard-cap the orphan buffer. If the sink is persistently unavailable
        // (e.g. a fuzz process that never called logInit()), stop appending past
        // kLogBufferOrphanCapBytes and count the drops instead of growing without
        // bound. Once g_logFp is valid again the normal path drains the buffer.
        if (g_logBuffer.size() < kLogBufferOrphanCapBytes) {
            g_logBuffer.append(lineBuf, (size_t)lineLen);
            g_logBufferCount++;
        } else {
            unsigned long dropped = g_logDroppedOrphan.fetch_add(1, std::memory_order_relaxed);
            if (dropped == 0) {
                fprintf(stderr, "AATPE: log orphan buffer hit %zu bytes; dropping further lines until sink recovers\n",
                        kLogBufferOrphanCapBytes);
            }
        }
        return;
    }

    // ERROR(0) and WARN(1) bypass buffer — flush then write immediately
    if (level <= 1) {
        flushLogBufferLocked();
        // WD-11: check fwrite return on the direct (unbuffered) ERROR/WARN path,
        // matching flushLogBufferLocked(). A short write (disk full / SIGPIPE /
        // fd closed mid-rotation) previously dropped the line silently. We log
        // the short-write to stderr best-effort; we do NOT retry (would risk
        // looping on a persistently full tmpfs).
        size_t nw = fwrite(lineBuf, 1, (size_t)lineLen, g_logFp);
        if (nw != (size_t)lineLen) {
            fprintf(stderr, "AATPE: log direct-write short write %zu/%zu\n",
                    nw, (size_t)lineLen);
        }
        fflush(g_logFp);
        return;
    }

    // INFO/DEBUG buffered — flush when buffer full (4KB or 100 entries)
    g_logBuffer.append(lineBuf, (size_t)lineLen);
    g_logBufferCount++;
    if (g_logBuffer.size() >= kLogBufferMaxBytes || g_logBufferCount >= kLogBufferMaxCount) {
        flushLogBufferLocked();
    }
}

// D-20: Clear/truncate the log file (called from processControlCommands "clear_log")
// P0-1: after freopen/fopen("w") the new file inherits the process umask and can
// land world-readable; re-assert 0600 immediately so a log-clear never leaves the
// log (package names / TIDs / scheduling decisions) world-readable.
//
// P1-fix (issue 3): freopen("w") / fopen("w") creates the file with umask-derived
// permissions (0644 under default umask) BEFORE fchmod(0600) runs, leaving a
// window where the truncated log is world-readable. Use open(O_WRONLY|O_CREAT|O_TRUNC,
// 0600) directly so the file is born 0600, then fdopen() it.
void logClear() {
    // G1-006: serialize with log rotation. performLogRotation() holds
    // g_logRotationMutex while it snapshots g_logFp=nullptr and does heavy I/O;
    // without this lock a concurrent clear could publish a truncated fp that the
    // rotation later fcloses, or truncate the inode being renamed. Order
    // g_logRotationMutex -> g_logMutex matches logMsg()'s acquisition order.
    std::lock_guard<std::mutex> rotLock(g_logRotationMutex);
    std::lock_guard<std::mutex> logLock(g_logMutex);
    if (g_logFp) {
        fclose(g_logFp);
        g_logFp = nullptr;
    }
    // Truncate/create directly with 0600 — no umask window.
    int fd = ::open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC | O_NOFOLLOW | O_CLOEXEC,
                    kLogFileMode);
    if (fd >= 0) {
        g_logFp = fdopen(fd, "w");
        if (!g_logFp) {
            ::close(fd);
        }
    } else {
        // Fallback: re-open append mode (file already exists from prior logs).
        mode_t oldMask = umask(0077);
        g_logFp = fopen(LOG_FILE, "a");
        umask(oldMask);
        if (g_logFp) {
            int cfd = fileno(g_logFp);
            if (cfd >= 0) fchmod(cfd, kLogFileMode);
        }
    }
}

// A8: host-only read-only accessors for the orphan-buffer regression test.
#ifdef AATPE_HOST_TEST
size_t aatpeTestLogOrphanBytes() {
    std::lock_guard<std::mutex> lock(g_logMutex);
    return g_logBuffer.size();
}
unsigned long aatpeTestLogOrphanDropped() {
    return g_logDroppedOrphan.load(std::memory_order_relaxed);
}
#endif
